BEGIN;
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('patient','physiotherapist')), care_code TEXT UNIQUE, therapist_id TEXT, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS profile_therapist_idx ON profiles(therapist_id);
CREATE TABLE IF NOT EXISTS prescriptions (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES profiles(id), therapist_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, instructions TEXT NOT NULL, reps BIGINT NOT NULL, sets BIGINT NOT NULL, minutes BIGINT NOT NULL, active BIGINT NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS prescription_patient_idx ON prescriptions(patient_id);
CREATE TABLE IF NOT EXISTS exercise_sessions (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES profiles(id), prescription_id TEXT NOT NULL REFERENCES prescriptions(id), exercise TEXT NOT NULL, instructions TEXT NOT NULL, target BIGINT NOT NULL, reps BIGINT NOT NULL DEFAULT 0, seconds BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL, started_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, finished_at BIGINT, heart TEXT NOT NULL DEFAULT '[]', connection TEXT NOT NULL DEFAULT 'disconnected', revision BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS session_patient_idx ON exercise_sessions(patient_id);
CREATE UNIQUE INDEX IF NOT EXISTS session_one_open_per_patient ON exercise_sessions(patient_id) WHERE status IN ('active','paused');
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY REFERENCES profiles(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('patient','physiotherapist')), password_hash TEXT NOT NULL, UNIQUE(email,role));
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_session_account_idx ON auth_sessions(account_id);
CREATE TABLE IF NOT EXISTS auth_limits (key TEXT PRIMARY KEY, count BIGINT NOT NULL DEFAULT 1, reset_at BIGINT NOT NULL);
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE profiles FROM anon, authenticated, PUBLIC;
ALTER TABLE prescriptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE prescriptions FROM anon, authenticated, PUBLIC;
ALTER TABLE exercise_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE exercise_sessions FROM anon, authenticated, PUBLIC;
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE accounts FROM anon, authenticated, PUBLIC;
ALTER TABLE auth_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE auth_sessions FROM anon, authenticated, PUBLIC;
ALTER TABLE auth_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE auth_limits FROM anon, authenticated, PUBLIC;
COMMIT;
